# -*- coding: utf-8 --

from taf.rfrl.cbts.connections.rest_conn_vcu import GenericCU
from robot.api import logger


class vCUOPE(GenericCU):

    def get_cells_number_from_vcu_webem(self, conn_alias='default'):
        cells_id_list = []
        cells_items = self.get_all_vcu_cells_statuses(conn_alias=conn_alias)

        for cell in cells_items:
            cells_id_list.append(cell['id'])
        return len(cells_id_list)

    def get_cells_id_list_from_vcu_webem(self, conn_alias='default'):
        cells_id_list = []
        cells_items = self.get_all_vcu_cells_statuses(conn_alias=conn_alias)

        for cell in cells_items:
            cells_id_list.append(cell['id'])
        return cells_id_list

    def get_all_vcu_cells_statuses(self, conn_alias='default'):
        cells_status = self.cu.get_cells_statuses(connection=conn_alias)
        logger.info('All of the cells information are as below\n{}'.format(cells_status))
        return cells_status

    def get_all_dus_summary_statuses(self, conn_alias='default'):
        dus_status = self.cu.get_du_state(connection=conn_alias)
        logger.info('All of the DUs summary information are as below\n{}'.format(dus_status))
        return dus_status

    def get_cu_sw_version_from_webem(self, conn_alias='default'):
        cu_state_data = self.cu.get_cu_state(connection=conn_alias)
        return cu_state_data['software_version']

    def get_cu_amfs_info_from_wbem(self, conn_alias='default'):
        cu_state_data = self.cu.get_cu_state(connection=conn_alias)
        return cu_state_data['amfs']

    def get_cu_mrbts_id_from_webem(self, use_m2m=True, conn_alias='default'):
        cu_state_data = self.cu.get_cu_state(use_m2m=use_m2m, connection=conn_alias)
        return 'MRBTS-{}'.format(cu_state_data['mrbts_id'])

    def get_vnfcs_states_from_webem(self, use_m2m=True, conn_alias='default'):
        cu_vnfcs_state = self.cu.get_vnfcs_states(use_m2m=use_m2m, connection=conn_alias)
        return cu_vnfcs_state

